	if not value.editMode: return

#	propName = "tableRowDroppedData" + str(system.kanoa.utilities.getUUID())	#make the propName the key to write too in the view.custom
	propName = "tableRowDroppedData"	#make the propName the key to write too in the view.custom

#	code =  """<img id="""+self.view.custom.uuid+"""<img style='display:none' src='/favicon.ico' onload=\"
	code =  """<img id="""+self.view.custom.uuid+""" style='display:none' src='/favicon.ico' onload=\"
		const view = [...window.__client.page.views._data.values()].find(view => view.value.mountPath == this.parentNode.parentNode.parentNode.getAttributeNode('data-component-path').value.split('.')[0]).value; 
		const uuid = view.custom.read('uuid');
		function ondrop(ev) {
			ev.preventDefault();
			ev.stopPropagation();
			const draggedId = JSON.parse(ev.dataTransfer.getData('text'));
			const droppedId = this.getAttribute('data-row-id');
			view.custom.write('tableRowDroppedData',{'draggedId':draggedId,'droppedId':droppedId});
		};
		function ondragstart(ev){

			ev.dataTransfer.setData('text', ev.target.getAttribute('data-row-id'));
		};
		function ondragover(ev){
			ev.preventDefault();
		};
    	const callbackTable = (mutationList, observer) => {
	    		document.querySelectorAll(`.psc-draggableParent-${uuid} .tr-group.ia_table__rowGroup`).forEach(e => {
				e.setAttribute('draggable',true);
				e.ondragstart = ondragstart;
				e.ondragover = ondragover;
				e.ondrop = ondrop;
			});	
		};

        const observerTable = new MutationObserver(callbackTable); 
        const tables = document.querySelectorAll(`.psc-draggableParent-${uuid}`);
        tables.forEach(table => observerTable.observe(table, { attributes: false, childList: true, subtree: true }));	
        document.querySelectorAll(`.psc-draggableParent-${uuid} .tr-group.ia_table__rowGroup`).forEach(e => {
            e.setAttribute('draggable',true);
            e.ondragstart = ondragstart;
            e.ondragover = ondragover;
            e.ondrop = ondrop;
        });	
	\"></img>""".replace("\n", "").replace("\t", "")
	return code

